INTRO = "After calming Joon-mo's suspicious mother over cafe drinks, Ye-jin shares instant noodles at home with her younger brother Ye-joon, who tells her bluntly why a man keeps a woman beside him for twenty years. Listen to their conversation first."
STORY = [('yejin', '신디가 우리를 딱 이렇게 먹이네.', 'Cindy really got us good like this.', [(1039, '신디가 우리를 딱 이렇게')], ''), ('colleague', '그럼 우리 일 위 후보 없이 방송 가는 거예요?', 'Then are we airing the broadcast without the first-place contender?', [(1040, '없이 방송 가는 거야')], ''), ('yejin', '아줌마, 성빈장은 저 앞에 중국집 이름이에요. 준모가 거기 좋아해요.', "Ma'am, that name on his card bill is the Chinese restaurant out front. Joon-mo loves it.", [(1067, '저 앞에 중국집 이름이에요'), (1068, '거기 준모가 좋아해요')], ''), ('yejin', '역시 아줌마는 사람 속 뒤집어 놓으시는 게 프로야.', "As expected, she is a total pro at turning a person's stomach upside down.", [(1085, '사람 속 뒤집어 놓으시는 거'), (1086, '프로야, 프로')], ''), ('yejoon', '누나, 나는 미래의 의사고 누나는 전문직인데 우리 처지가 너무 초라하지 않냐?', "Sis, I am a future doctor and you are a professional, yet isn't our situation kind of shabby?", [(1089, '누나, 나는 미래의 의사고'), (1090, '전문직인데')], ''), ('yejin', '전문직이 부동산 못 당해요.', 'A professional salary cannot beat real estate.', [(1092, '전문직이 부동산 못 당해요')], ''), ('yejoon', '내가 전에 말했잖아, 준모 형이랑 결혼해서 우리 집 되찾으라고.', 'I told you before, marry Joon-mo and win back our family apartment.', [(1095, '내가 전에 말했잖아'), (1096, '결혼해서 우리 집')], ''), ('yejin', '시끄럽다고! 라면이나 드세요.', 'Be quiet! Just eat your noodles.', [(1097, '시끄럽다고'), (1102, '라면이나')], ''), ('yejoon', '이십 년 넘게 친구 설정으로 지냈는데 쉽진 않겠지.', "You lived as friends for over twenty years, so changing that won't be easy.", [(1103, '넘게 친구 설정으로 지냈는데'), (1104, '쉽진 않겠지')], ''), ('yejoon', '남자가 어떤 여자를 친한 친구라면서 오래오래 옆에 두는 건 마음이 있다는 얘기야.', 'When a man keeps a woman right beside him for ages calling her a close friend, it means feelings are there.', [(1107, '남자가 어떤 여자를'), (1108, '친한 친구라면서'), (1109, '오래오래 옆에 두는 거'), (1111, '있다는 얘기야')], ''), ('yejoon', '정말로 아닌 여자랑은 친구도 안 하거든.', "Because a man won't even be friends with a woman he truly feels nothing for.", [(1113, '정말로 아닌 여자랑은'), (1114, '친구도 안 하거든')], ''), ('yejin', '지난번도 느낀 건데 너 누구한테 연애를 가르치니?', 'I noticed this last time too—who do you think you are lecturing about romance?', [(1115, '지난번도 느낀 건데 너'), (1116, '가르치니')], '')]
OPENER = "Now let's go through it line by line with the English translation."
WALK = [(0, None, "'Cindy really got us good like this.'"), (1, None, "'Then are we airing the broadcast without the first-place contender?'"), (2, None, "'Ma'am, that name on his card bill is the Chinese restaurant out front. Joon-mo loves it.'"), (3, None, "'As expected, she is a total pro at turning a person's stomach upside down.'"), (4, None, "'Sis, I am a future doctor and you are a professional, yet isn't our situation kind of shabby?'"), (5, None, "'A professional salary cannot beat real estate.'"), (6, None, "'I told you before, marry Joon-mo and win back our family apartment.'"), (7, None, "'Be quiet! Just eat your noodles.'"), (8, None, "'You lived as friends for over twenty years, so changing that won't be easy.'"), (9, None, "'When a man keeps a woman right beside him for ages calling her a close friend, it means feelings are there.'"), (10, None, "'Because a man won't even be friends with a woman he truly feels nothing for.'"), (11, None, "'I noticed this last time too—who do you think you are lecturing about romance?'")]
